contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint deposit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (deposit)); require(deposit <= 1000000000000000000000000000000);
        require(address(this).balance >= deposit);

        c.addToBalance{value: deposit}(); if (__ESBMC_reverted()) return;
        uint beforeBalance = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractEther = address(c).balance;
        uint beforeTestEther = address(this).balance;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBalance = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractEther = address(c).balance;
        uint afterTestEther = address(this).balance;

        assert(
            reverted
                ? (afterBalance == beforeBalance && afterContractEther == beforeContractEther && afterTestEther == beforeTestEther)
                : (afterBalance == 0 && beforeBalance + beforeTestEther == afterBalance + afterTestEther && beforeContractEther == afterContractEther + beforeBalance)
        );
    }

    receive() external payable {}
}

