pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 deposit) internal {
        deposit = bound(deposit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= deposit);
        try c.addToBalance{value: deposit}() {} catch { return; }
        uint256 beforeBalance;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeBalance = __r; } catch { return; }
        uint beforeContractEther = address(c).balance;
        uint beforeTestEther = address(this).balance;
        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterBalance;
        try c.getBalance(address(this)) returns (uint256 __r) { afterBalance = __r; } catch { return; }
        uint afterContractEther = address(c).balance;
        uint afterTestEther = address(this).balance;
        assertTrue(reverted
                ? (afterBalance == beforeBalance && afterContractEther == beforeContractEther && afterTestEther == beforeTestEther)
                : (afterBalance == 0 && beforeBalance + beforeTestEther == afterBalance + afterTestEther && beforeContractEther == afterContractEther + beforeBalance));
    }

    function testFuzz_run(uint256 deposit) public {
        _run(deposit);
    }

    receive() external payable {}
}
